from collections import Counter

def can_rearrange_to_smaller(s, t):
    cs, ct = Counter(s), Counter(t)
    for char in 'abcdefghijklmnopqrstuvwxyz':
        if cs[char] > 0 and ct[char] > 0:
            return True
        elif cs[char] > 0:
            if any(ct[other_char] > 0 for other_char in 'abcdefghijklmnopqrstuvwxyz' if other_char > char):
                return True
        elif ct[char] > 0:
            if any(cs[other_char] > 0 for other_char in 'abcdefghijklmnopqrstuvwxyz' if other_char > char):
                return False
    return False

